scwin.ipt_realSalesAmt_onkeyup = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        $c.util.getComponent('txt_realSalesAmtHanview').setValue($c.num.formatNumberKor(String((((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar))))) == null ? '' : (((selfVar) && (selfVar).getValue) ? (selfVar).getValue() : ((((selfVar) && typeof (selfVar).val === 'function') ? (selfVar).val() : (((selfVar) && (selfVar).value !== undefined) ? (selfVar).value : (selfVar)))))).replace(/,/g, '')));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldbnf50001.ipt_realSalesAmt_onkeyup' }); }
};

