///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name mpd_files_selectCallback
 * @description mpd files select Callback 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.mpd_files_selectCallback = function (data) { const d = $c.util.getComponent('dlt_files'); if (!d) { return; } const rows = []; for (let i = 0; i < (data || []).length; i++) { rows.push({ FILE_NM: data[i].name, FILE_SIZE: String(data[i].size), CHK: '' }); } if (rows.length) { d.insertJSON(d.getRowCount(), rows); } };

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name Cal_sale_amt
 * @description Cal sale amt 처리
 * @param {*} fm fm
 * @returns {void}
 * @hidden N
 */
scwin.Cal_sale_amt = function (fm) {
    if ($c.str.getByteLength($c.util.getComponent('ipt_bndTotSales').getValue()) === 0) {
        $c.util.getComponent("ipt_realSalesAmt").setValue('');
        return;
    }
    if ($c.str.getByteLength($c.util.getComponent('ipt_redmptAmt').getValue()) === 0) {
        $c.util.getComponent("ipt_realSalesAmt").setValue('');
        return;
    }
    const sale_tot_amt = Del_MoneyComma_Value($c.util.getComponent('ipt_bndTotSales').getValue());
    const rdmp_amt = Del_MoneyComma_Value($c.util.getComponent('ipt_redmptAmt').getValue());
    let real_sales_amt = '';
    if (!$c.num.isNumber(sale_tot_amt)) {
        return false;
    }
    real_sales_amt = parseInt(sale_tot_amt) - parseInt(rdmp_amt);
    $c.util.getComponent("ipt_realSalesAmt").setValue(real_sales_amt);
    $c.num.formatNumber($c.util.getComponent('ipt_realSalesAmt'));
    $("input[name='real_sales_amt']").trigger('onkeyup');
    return true;
};
